-- hrm.tg_loans_rules: A loan is never deleted; its terms never change once approved; its status only moves forward and ended loans change no more; refused with constraint ck_loans_rules.
create or replace function hrm.tg_loans_rules() returns trigger
language plpgsql as $fn$
begin
    if tg_op = 'DELETE' then
        raise exception 'loan %: a loan is never deleted; cancel it', old.id
            using errcode = '23514', constraint = 'ck_loans_rules';
    end if;
    if tg_op = 'INSERT' then
        if new.status <> 'applied' or new.principal <= 0 or new.installments < 1 or new.interest_rate < 0 then
            raise exception 'loan %: a new loan is applied for with a principal above zero and at least one installment', new.id
                using errcode = '23514', constraint = 'ck_loans_rules';
        end if;
        return new;
    end if;
    if old.status in ('rejected', 'settled', 'written_off', 'cancelled') then
        raise exception 'loan %: a loan that ended (%) changes no more', old.id, old.status
            using errcode = '23514', constraint = 'ck_loans_rules';
    end if;
    if new.status <> old.status and not (
           (old.status = 'applied' and new.status in ('approved', 'rejected', 'cancelled'))
        or (old.status = 'approved' and new.status in ('active', 'cancelled'))
        or (old.status = 'active' and new.status in ('settled', 'written_off'))) then
        raise exception 'loan %: a loan cannot move from % to %', old.id, old.status, new.status
            using errcode = '23514', constraint = 'ck_loans_rules';
    end if;
    if old.status <> 'applied' and (
           new.company_id <> old.company_id or new.employment_id <> old.employment_id or new.loan_type_id <> old.loan_type_id or new.loan_no <> old.loan_no
        or new.principal <> old.principal or new.currency_code <> old.currency_code or new.interest_rate <> old.interest_rate
        or new.installments <> old.installments or new.interest_method is distinct from old.interest_method
        or new.guarantor_employment_id is distinct from old.guarantor_employment_id) then
        raise exception 'loan %: the terms of an approved loan never change', old.id
            using errcode = '23514', constraint = 'ck_loans_rules';
    end if;
    return new;
end
